"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  type Ref,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** One action in the row. The label stays visible, so the row never relies on an icon alone. */
export interface OverflowAction {
  id: string;
  label: string;
  icon?: ReactNode;
  onSelect: () => void;
  disabled?: boolean;
}

/** Props for a row of actions that keeps the main ones in view and opens the rest on demand. */
export type OverflowActionsProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Names the row for screen readers, for example "Message actions". */
  label: string;
  /** The actions that are always in view. Keep this to two or three. */
  actions: OverflowAction[];
  /** The actions that open on demand, after the main ones. */
  moreActions: OverflowAction[];
  moreLabel?: string;
  lessLabel?: string;
};

// Damping 41 is 2 × √420, rounded up: critically damped, so the row widens without overshoot.
const WIDEN: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
const SWAP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
// Reduced motion snaps the width and keeps the fade, because a fade is not motion.
const SNAP_AND_FADE: Transition = { width: { duration: 0 }, opacity: { duration: 0.15 } };
const FADE: Transition = { duration: 0.15 };
const FOLDED = { width: 0, opacity: 0 };
const UNFOLDED = { width: "auto", opacity: 1 };

function MoreGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <circle cx="3.5" cy="8" r="1.25" />
      <circle cx="8" cy="8" r="1.25" />
      <circle cx="12.5" cy="8" r="1.25" />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m4.5 4.5 7 7M11.5 4.5l-7 7" strokeLinecap="round" />
    </svg>
  );
}

const ACTION_BUTTON =
  "inline-flex min-h-11 shrink-0 cursor-pointer touch-manipulation items-center gap-2 whitespace-nowrap rounded-full px-4 text-sm font-medium text-foreground outline-none hover:bg-muted active:scale-97 disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring motion-safe:transition motion-safe:duration-150 sm:min-h-9";

function ActionButton({ action, onSelected, ref }: { action: OverflowAction; onSelected?: () => void; ref?: Ref<HTMLButtonElement> }) {
  return (
    <button
      ref={ref}
      type="button"
      disabled={action.disabled}
      onClick={() => {
        action.onSelect();
        onSelected?.();
      }}
      className={ACTION_BUTTON}
    >
      {action.icon ? (
        <span aria-hidden="true" className="flex size-4 items-center justify-center">
          {action.icon}
        </span>
      ) : null}
      {action.label}
    </button>
  );
}

/**
 * Keeps the main actions in view and opens the rest on demand. The row widens
 * in place to show the extra actions, so they appear beside the ones the
 * person already sees instead of in a menu somewhere else.
 */
export function OverflowActions({
  label,
  actions,
  moreActions,
  moreLabel = "More actions",
  lessLabel = "Fewer actions",
  className,
  onKeyDown,
  ...divProps
}: OverflowActionsProps) {
  // The extra actions are clipped while the row widens, then scroll once it is open,
  // so a narrow screen still reaches every action.
  const [row, setRow] = useState<"closed" | "opening" | "open">("closed");
  const open = row !== "closed";
  const reduceMotion = useReducedMotion();
  const hiddenIcon = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8, filter: "blur(0.25rem)" };
  const moreId = useId();
  const toggleRef = useRef<HTMLButtonElement>(null);
  const firstMoreRef = useRef<HTMLButtonElement>(null);
  const focusFirstMore = useRef(false);

  // A keyboard user who opens the row lands on the first new action. A pointer
  // user keeps focus where they clicked, because they can see what appeared.
  useEffect(() => {
    if (!open || !focusFirstMore.current) return;
    focusFirstMore.current = false;
    firstMoreRef.current?.focus();
  }, [open]);

  const close = () => {
    setRow("closed");
    toggleRef.current?.focus();
  };

  const toggle = (event: MouseEvent<HTMLButtonElement>) => {
    // A press from Enter or Space reports zero clicks.
    focusFirstMore.current = !open && event.detail === 0;
    setRow(open ? "closed" : "opening");
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.key !== "Escape" || !open) return;
    event.preventDefault();
    close();
  };

  return (
    <div
      {...divProps}
      role="group"
      aria-label={label}
      onKeyDown={handleKeyDown}
      className={cn("inline-flex max-w-full items-center gap-1 rounded-full border border-border bg-card p-1", className)}
    >
      {actions.map((action) => (
        <ActionButton key={action.id} action={action} />
      ))}
      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            key="more"
            id={moreId}
            initial={FOLDED}
            animate={UNFOLDED}
            exit={FOLDED}
            transition={reduceMotion ? SNAP_AND_FADE : WIDEN}
            // The exit also completes here, so only the opening counts. The scrollbar is hidden:
            // touch, a trackpad and Tab still reach every action.
            onAnimationComplete={(definition) => {
              if (definition === UNFOLDED) setRow("open");
            }}
            className={cn("flex min-w-0 items-center gap-1", row === "open" ? "overflow-x-auto [scrollbar-width:none]" : "overflow-hidden")}
          >
            {moreActions.map((action, index) => (
              <ActionButton
                key={action.id}
                ref={index === 0 ? firstMoreRef : undefined}
                action={action}
                // The chosen action leaves with the row, so focus returns to the toggle instead of the page.
                onSelected={close}
              />
            ))}
          </motion.div>
        ) : null}
      </AnimatePresence>
      <button
        ref={toggleRef}
        type="button"
        aria-expanded={open}
        aria-controls={open ? moreId : undefined}
        aria-label={open ? lessLabel : moreLabel}
        onClick={toggle}
        className="grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full bg-primary text-primary-foreground outline-none active:scale-90 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition motion-safe:duration-150 sm:size-9"
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={open ? "less" : "more"}
            initial={hiddenIcon}
            animate={{ opacity: 1, scale: 1, filter: "blur(0rem)" }}
            exit={hiddenIcon}
            transition={reduceMotion ? FADE : SWAP}
            className="col-start-1 row-start-1 flex"
          >
            {open ? <CrossGlyph /> : <MoreGlyph />}
          </motion.span>
        </AnimatePresence>
      </button>
    </div>
  );
}
